using RouterStudio.Core.Services;using RouterStudio.Core.Contracts;using RouterStudio.Desktop.Presentation;
namespace RouterStudio.Core.Tests;
[TestClass] public sealed class LifecycleTests {
 private sealed class Backend:IStudioBackend {public TaskCompletionSource<StudioResult> Pending=new();public int Calls;public Task<StudioSnapshot> GetSnapshotAsync(CancellationToken ct)=>Task.FromResult(new StudioSnapshot{SnapshotDigest=new string('a',64),Connection=new(){Selected="router"},RouterHealth=new(){Reachable=false}});public Task<StudioResult> ExecuteAsync(StudioRequest r,SecretInput? s,CancellationToken ct){Calls++;return Pending.Task;}}
 [TestMethod] public async Task ExitDuringMutationWaitsAndBlocksNewActions(){var backend=new Backend();var shell=new ShellViewModel(backend);await shell.RefreshAsync();var mutation=shell.ExecuteMutationAsync(StudioRequest.Create("official"));shell.BeginExit();var idle=shell.WaitForIdleAsync();Assert.IsFalse(idle.IsCompleted);await shell.ExecuteMutationAsync(StudioRequest.Create("router",new{ack=true}));Assert.AreEqual(1,backend.Calls);backend.Pending.SetResult(StudioResult.Failure("config_changed"));await mutation;await idle;Assert.IsFalse(shell.CanMutate);}
 [TestMethod] public async Task TrayStateDistinguishesSelectedFromHealthy(){var shell=new ShellViewModel(new Backend());await shell.RefreshAsync();Assert.IsTrue(shell.TrayText.Contains("Unreachable"));Assert.IsTrue(shell.TrayText.Contains("8stoken"));}
 [TestMethod] public void StartupSettingTouchesOnlyOwnedEntryAndRetainsLegacyLauncher(){var root=Path.Combine(Path.GetTempPath(),"Studio startup "+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{var registry=new Dictionary<string,string>{{"Unrelated","keep"}};var startup=new StartupPreferences(name=>registry.GetValueOrDefault(name),(name,value)=>{if(value is null)registry.Remove(name);else registry[name]=value;},()=>true);startup.SetRouter(true,"owned router command");Assert.AreEqual(1,registry.Count);startup.SetRouter(false,"owned router command");Assert.AreEqual(1,registry.Count);Assert.IsNotNull(startup.Notice);startup.SetApp(true,"owned desktop command");Assert.AreEqual("keep",registry["Unrelated"]);startup.SetApp(false,"owned desktop command");Assert.AreEqual(1,registry.Count);}finally{Directory.Delete(root);}}
}
